  WHERE work_key LIKE 'ws:%';

CREATE OR REPLACE FUNCTION montree_seed_writing_shelf_works(p_classroom_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_area_id uuid;
BEGIN
  -- Language area, values identical to DEFAULT_AREAS['language'] in
  -- app/api/montree/curriculum/route.ts and to migrations 344/346.
  INSERT INTO montree_classroom_curriculum_areas
    (classroom_id, area_key, name, name_chinese, icon, color, sequence, is_active)
  VALUES
    (p_classroom_id, 'language', 'Language', '语言', '📚', '#EC4899', 4, true)
  ON CONFLICT (classroom_id, area_key) DO NOTHING;

  SELECT id INTO v_area_id
    FROM montree_classroom_curriculum_areas
   WHERE classroom_id = p_classroom_id AND area_key = 'language';

  INSERT INTO montree_classroom_curriculum_works (
    classroom_id, area_id, work_key, name, name_chinese, name_zh, description,
    age_range, sequence, is_active,
    direct_aims, indirect_aims, materials, control_of_error, prerequisites,
    quick_guide, presentation_steps, presentation_notes,
    parent_description, why_it_matters, video_search_terms
  )
  SELECT
    p_classroom_id, v_area_id, v.work_key, v.name, v.name_chinese, v.name_chinese, v.description,
    v.age_range, v.sequence, true,
    v.direct_aims::jsonb, v.indirect_aims::jsonb, v.materials::jsonb,
    v.control_of_error, v.prerequisites::jsonb,
    v.quick_guide, v.presentation_steps::jsonb, v.presentation_notes,
    v.parent_description, v.why_it_matters, v.video_search_terms
  FROM (VALUES
    ('ws:1', 'Writing Shelf tray 1 · Sound boxes', '声音盒', 'Sound boxes', '4-6', 901, '["Hear a spoken word as separate sounds and count them","Push one counter into one box for each sound heard","Swap every counter for the letter that spells that sound"]', '["Orthographic mapping — sound-to-letter links, slowed down enough to watch","Left-to-right order","Self-checking against a leftover box instead of against an adult"]', '["2 sound-frame mats: one resting 3-box side up, one resting 4-box side up","10 glass counters, one colour, in a small dish","6 object-box miniatures: pig, cat, sun, bed, mug, hat","1 lidded box of 16 letters: s a t p i n m d g o c k e u b h"]', 'The number of boxes matches the number of sounds. A leftover box, or a counter with nowhere to go, tells him to say the word again — you do not have to.', '["Knows the sounds of the sandpaper letters he will need","Can hold a spoken word long enough to say it stretched"]', 'Say it · push it · letter it. He takes an object, says its name slowly, pushes one counter into one box per sound, then swaps every counter for a letter.', '[{"step":1,"title":"Sit on his right","description":"Sit on his right, so your hand does not cross in front of his eyes."},{"step":2,"title":"The mat","description":"Put the 3-box mat down in front of him."},{"step":3,"title":"The object","description":"Take the sun from the basket, stand it above the mat: \"This is a sun.\"","tip":"Use sun the first time — every one of its sounds can be stretched."},{"step":4,"title":"The counters","description":"Slide him the counters. Take three out, line them up under the mat."},{"step":5,"title":"Watch my mouth","description":"Say: \"Watch my mouth.\" Stretch it in one breath, no gaps, twice: ssss—uuuu—nnnn. Second time, tap once per sound.","tip":"Never \"suh-uh-nuh\" — an added \"uh\" is a fourth sound and will cost you months."},{"step":6,"title":"One counter, one sound","description":"Say ssss, push a counter into box one. uuuu — box two. nnnn — box three. Then normal speed: \"sun.\""},{"step":7,"title":"Your turn","description":"Clear the counters, put the sun back, push the basket to him: \"Your turn.\" Then stop talking."},{"step":8,"title":"Open the letter box","description":"Once he can do three objects alone, open the letter box: \"What sound is in this box? Find me the s.\" He swaps each counter for its letter."},{"step":9,"title":"Read it back","description":"Read it back together, finger under each letter, then faster: s–u–n. Sun."},{"step":10,"title":"Reset the tray","description":"Everything goes back on the tray before he chooses another object. That part is the lesson too."}]', 'Stretchy and stoppy sounds: you can hold /s/ /m/ /n/ /f/ /l/ and every vowel; /p/ /t/ /k/ /g/ /b/ /d/ stop — say those crisply and tap once instead. Introduce the six miniatures in this order across the weeks: sun → mug → hat → bed → pig → cat (sun leads because every one of its sounds stretches). Week 3 brings out the 4-box side with the tile-tin words naps → snap → spat → spit → stuck — naps and snap are the same four tiles rearranged, the rest change one tile at a time. The letter box is the SIXTEEN-TILE box: s a t p i n m d g o c k e u b h, and it stays shut for the first few weeks. If all three counters go in at once, cover the last two boxes with your hand. If he says letter names ("ess" for /s/), stop for today and do two minutes of sandpaper letters.', 'The child says a word slowly, pushes one counter into a box for every sound he hears, then swaps each counter for the matching letter. It matters because he can already read pig off a card — here he learns to hear that pig is really three sounds.', 'A counter carries no spelling — it only marks that a sound happened, so the child hears sounds apart before choosing letters for them. Joseph (2000) found at-risk kindergartners taught with word boxes gained more in phoneme awareness, letter-sound knowledge and spelling than children taught the same content without them. Move him on when he places counters for a four-sound word unprompted, spots his own leftover box, and swaps every counter for a letter on three different objects in one sitting.', 'Montessori Elkonin sound boxes phoneme counters CVC word boxes presentation'),
    ('ws:2', 'Writing Shelf tray 2 · Movable alphabet', '活动字母', 'Movable alphabet', '4-6', 902, '["Spell a word he chose himself, with nothing holding his place for him","Lay the letters left to right and read the word back","Make a spelling choice — c or k — instead of waiting to be told"]', '["Composition before handwriting: the motor load is removed","Invented spelling kept alive, because nothing is corrected on this tray","Independence — he hunts the letter box himself"]', '["1 large movable alphabet, complete, in its own box beside the tray","1 object box, 8 miniatures — Set A: cat, pig, dog, pot, pan, tin, mop, peg; Set B rotates in: sun, mug, hat, bed, nut, bin, cot, kit","1 felt work mat, about 40 x 30 cm","Sandpaper letters nearby, for a forgotten letter shape. No pencil."]', 'The object in his hand. He sounds out what he laid down and hears whether it matches. Spelling is not corrected on this tray — that happens on Tray 4.', '["Can place counters for a three-sound word on Tray 1 without help","Knows the sounds of the letters in the set he is given"]', 'Build the word, do not write it. He puts one object at the top of the mat, says the word slowly, lays the letters left to right, and reads it back.', '[{"step":1,"title":"Mostly silence","description":"Sit on his right. This lesson is mostly silence — hunting through the letter box is the work."},{"step":2,"title":"The mat","description":"Unroll the felt mat. Open the alphabet box beside it, letters facing him."},{"step":3,"title":"One object only","description":"Take the cat out of the box. Stand it at the top-left of the mat. Nothing else goes on the mat."},{"step":4,"title":"He names it","description":"Ask: \"What is it?\" He says cat — the word is his, not yours."},{"step":5,"title":"Say it slowly","description":"Say: \"Say it slowly.\" He stretches it: k—a—t.","tip":"If he cannot stretch it, stop and go back to Tray 1 for a week. No amount of this tray will fix that."},{"step":6,"title":"First sound","description":"Say: \"What is the first sound? Find that letter.\" Wait. Let him search the whole box. Do not point."},{"step":7,"title":"Left edge","description":"He lays the letter at the left edge of the mat, next to the object."},{"step":8,"title":"Across the word","description":"Say: \"Say it again. What comes next?\" The next letter goes touching the first. Repeat for the last sound.","tip":"Never say a letter name and never say \"no\"."},{"step":9,"title":"Read it to me","description":"When finished: \"Read it to me.\" He touches each letter and sounds it out. If it reads back wrong he will usually hear it and fix it."},{"step":10,"title":"Put it away","description":"Letters back in their compartments; he takes the next object. A built word is never left out to admire."}]', 'The thing you must not do: he builds kat — say nothing. If you cannot bear the silence, say "Yes — that says cat" and move on. He meets the c on Tray 4, on a card, in private. Correct him here and he learns to wait for you before he commits, and a child who waits cannot spell. Sets are LOCKED: Set A cat pig dog pot pan tin mop peg for weeks 1-2, Set B sun mug hat bed nut bin cot kit once Set A is fluent — mop, peg, nut and bin deliberately pre-seed Tray 3 chain starts. If he asks "is that right?", answer only "Read it to me and see." If he builds ct with no vowel, back to Tray 1 for a week with the same object.', 'The child picks an object, says its name slowly, and lays out movable letters left to right to spell it — no pencil, and no mat with boxes telling him how many letters to reach for. It matters because it is the first time the word lives only in his head, with nothing else holding his place for him.', 'Berninger et al. (2002) found that in young writers it is transcription — forming letters, recalling spellings — that limits how much gets written, not ideas; taking the pencil out of the loop hands his whole attention back to the spelling choice. Montessori (1912) put composing before handwriting for exactly this reason and Lillard (2017) collects the classroom evidence. Move him on when he builds a word you never named, starts at the left edge without a reminder, and builds three words in one sitting without asking whether any of them are right.', 'Montessori movable alphabet presentation object box building CVC words'),
    ('ws:3', 'Writing Shelf tray 3 · Word chains', '词链', 'Word chains', '4-6', 903, '["Change exactly one sound in a word and read the new word","Reach into a word and move one part without rebuilding the rest","Say WHICH sound changed, not only which letter moved"]', '["Minimal-pair listening, including the /ae/-/e/ contrast Mandarin-L1 ears find hard","Orthographic mapping: a word is a row of sound-to-letter links, separately movable","Self-checking against the back of the chain card"]', '["1 chain board: a strip with 3 letter slots and a 4th spare slot, kept 4-frame side up","1 tin of 30 letter tiles — doubles of all fifteen: a b c d e g h i m n o p r t u","6 chain cards (front: start word + picture; back: the full chain)"]', 'The back of the chain card lists the chain in order. And the rule itself is a control: if more than one tile moved, something went wrong.', '["Builds a three-sound word with the movable alphabet on Tray 2","Reads back a word he built himself"]', 'Change exactly one sound. He builds the first word on the board, hears the next word, changes one letter, and reads the new word aloud before moving on.', '[{"step":1,"title":"Show the card","description":"Take the top chain card, show him the picture: \"Mop.\""},{"step":2,"title":"Build it yourself","description":"Build mop in the slots yourself, saying each sound as it lands: /m/ /o/ /p/."},{"step":3,"title":"He reads it","description":"Push the board to him: \"Read it.\" He reads mop."},{"step":4,"title":"The move","description":"Say: \"Now make hop.\" Say the pair close together, twice: mop … hop. mop … hop.","tip":"A gap between the two words lets him forget the first, and then he rebuilds."},{"step":5,"title":"Wait","description":"Wait. Do not point at the slot that changes — the waiting is the whole lesson."},{"step":6,"title":"Read the new word","description":"When he lifts a tile, say nothing until it lands, then: \"Read it.\" He reads hop."},{"step":7,"title":"Again","description":"Say: \"Now make hot.\" Same rhythm: hop … hot. hop … hot."},{"step":8,"title":"Five words","description":"Work through five words. If he stalls, stretch only the differing part: mmmm–op … hhhh–op."},{"step":9,"title":"He checks himself","description":"Turn the card over. He checks the chain against the back himself."},{"step":10,"title":"Read the whole chain","description":"Every time: he reads the whole finished chain aloud, top to bottom. That is where it gets stored."}]', 'Six chains, one 30-tile tin — doubles of all fifteen letters, so a chain never stalls for want of a second letter. A beginner only gets that one chain''s tiles out, six or seven, never the whole tin. Week 2 changes only the first sound (cat, sat, mat, hat, pat); week 3 only the vowel (pig, peg, pug), which is harder and transfers most to spelling; week 4 mixes the positions. Two of the printed chains hinge on the vowel pair /ae/-/e/ — pan→pen and bed→bad — which is genuinely hard for a Mandarin speaker: sit those two cards side by side on their own, exaggerating the jaw drop on /ae/, before either turns up inside a longer chain. If he makes a real word that is not the target (mop to map), praise it, then: "Good word. Now make hop."', 'The child builds a word with letter tiles, then you say a new word that differs by exactly one sound, and he changes exactly one tile to make it. It matters because a child who can build mop but sweeps the whole thing away when you ask for hop is treating mop as one memorised lump, not as parts he can reach into and change.', 'McCandliss, Beck, Sandak & Perfetti (2003) built a whole reading intervention out of this single move — change one letter, read the new word — and struggling readers gained more from it than from ordinary phonics practice. It forces attention onto the one position that changed, the spot a child would otherwise skate over. Move him on when he changes the single tile without rebuilding on three chains running, can say which SOUND changed, and predicts a word in the chain before you say it.', 'word building minimal pairs word chains letter tiles change one sound phonics'),
    ('ws:4', 'Writing Shelf tray 4 · Dictation', '听写', 'Dictation', '4-6', 904, '["Write a word on blank paper his own way, from the sounds he hears","Turn the card over, compare, and correct himself once","Meet the heart words that cannot be sounded out"]', '["A control of error on blank paper, which nothing before this tray had","Correction that lands in the second after writing, not a day later in a marked book","Keeps invented spelling safe on Trays 2, 6 and 7 by giving correction one named home"]', '["12 flip cards (front: photo; back: the word in the stroke font, 48 pt): pig cat hat rug bed mug cot dog bag pen jam log","1 small notebook per child, in a labelled box","2 sharpened pencils in a pot","1 heart-word ring: a, an, I, the, ate"]', 'The printed word on the back, in the same stroke font he traces. He never has to ask you, and you never have to mark a book.', '["Builds three-sound words with the movable alphabet on Tray 2","Forms most of his letters well enough to be read back"]', 'Write it · flip it · fix it yourself. He looks at the picture, says the word, writes it his own way, then turns the card over, compares, and rewrites it once underneath.', '[{"step":1,"title":"Sit beside him","description":"Sit beside him, not opposite. Open his notebook at the next clean page."},{"step":2,"title":"Picture only","description":"Take the top card, show him only the picture. Do not say the word aloud."},{"step":3,"title":"He names it","description":"Ask: \"What is it?\" He says mug — the word is his, not yours."},{"step":4,"title":"Say it slowly","description":"Say: \"Say it slowly.\" He stretches it. Tap once per sound, the same taps as Tray 1."},{"step":5,"title":"Now write it","description":"Say: \"Now write it.\" Then say nothing — no spelling, no humming. Turn your body slightly away."},{"step":6,"title":"Turn it over","description":"When the pencil stops: \"Turn it over.\""},{"step":7,"title":"Silence","description":"He compares to the back in silence — do not read the word out and do not point at the letter he missed."},{"step":8,"title":"Once, underneath","description":"Say: \"Write it once more, underneath.\" Once — not a whole line."},{"step":9,"title":"Stop at four","description":"Card to the back of the stand, next card. Stop at four — that is a whole session."},{"step":10,"title":"Heart words","description":"For a heart word, be honest: \"This one you cannot sound out. Look at it, then write it.\""}]', 'The dictation deck is the twelve photo words cat pig hat mug bed dog pen bag log rug cot jam, and the heart-word ring starts at exactly five: a, I, ate, the — plus an. Add one heart word a week, never two. This is the ONLY tray on the shelf where a spelling is corrected, so shelve it visibly apart from Trays 2 and 6; a child who asks you to fix his story book is told "Not in your book. We do that on the card tray." If he peeks at the back first, turn the stand around and hand him one card at a time. If he is right on every card, add a four-sound word, then a heart word.', 'The child looks at a picture, writes the word his own way in his notebook, then flips the card over to see the real spelling and corrects himself. It matters because this is the only tray where a spelling gets corrected — and the card does the correcting, not you, in the one second after he wrote it, which is the only moment correction actually helps.', 'Graham & Santangelo (2014) pooled the spelling-instruction studies and found that teaching spelling explicitly improves spelling and carries over into word reading. With twenty children you cannot mark twenty notebooks a day, but a card corrects one child in the second after he wrote it. Move him on when three cards in a row match the back first time, when he turns the card over unprompted, and when he corrects one letter instead of rewriting the word from scratch.', 'Montessori dictation self-checking flip cards heart words phonics spelling'),
    ('ws:5', 'Writing Shelf tray 5 · Sentence builder', '造句', 'Sentence builder', '4-6', 905, '["Lay word cards along the sentence line to build a sentence he chose","End it with a punctuation tile and read it aloud, one touch per word","Copy his own sentence onto a strip, with gaps and his own full stop"]', '["Composing is finished before the pencil comes out, so nothing is lost mid-word","Word spacing, arriving from the gaps between cards","The first sorting of naming / doing / small words — grammar a year before Tray 8"]', '["1 tin of about 40 word cards from the readers, in three compartments: naming words · doing words · small joining words","1 heart-word ring (its own copy, same words as Tray 4)","3 punctuation tiles: full stop, question mark, exclamation mark","10 blank lined sentence strips and 1 pencil"]', 'Reading it out loud. If it does not make sense, it is not a sentence, and he hears that himself. Every strip must end with a mark — a strip with no mark goes back.', '["Writes single words from Tray 4 that can be read back","Reads back a word or short phrase he built himself"]', 'Lay it out, then copy it down. He builds a sentence along the sentence line, ends it with a tile, reads it aloud with a finger, then copies it onto a strip and adds his own full stop.', '[{"step":1,"title":"The sentence line","description":"Lay the sentence line in front of him, running left to right."},{"step":2,"title":"Three compartments","description":"Open the tin: \"These are things. These are what they do. These are the little words that hold them together.\""},{"step":3,"title":"Lay a sentence","description":"Take the, pig, is, big. Lay them down one at a time, saying each word out loud as it lands."},{"step":4,"title":"The gap","description":"Point at the gap between two cards: \"See the space? Words need room.\"","tip":"This is the sentence that fixes thepigisbig, and it has to be said at the cards, not at his writing."},{"step":5,"title":"A sentence has to stop","description":"Take the full-stop tile: \"A sentence has to stop.\" Put it down firmly at the end."},{"step":6,"title":"Read it together","description":"Read it together, finger sliding under each card, one touch per word."},{"step":7,"title":"Break it on purpose","description":"Swap big for a card that does not fit — the pig is mud. Read it again: \"Does that work?\" Let him hear that it does not. Laugh about it.","tip":"The step everyone skips. Breaking a sentence on purpose is what makes reading it back worth doing."},{"step":8,"title":"Make me one","description":"Push the tin to him: \"Make me one.\" Whatever he makes, read it with him."},{"step":9,"title":"Now write it down","description":"Give him a strip and the pencil: \"Now write it down.\" He copies from his own cards, which are right there, so nothing has to be remembered."},{"step":10,"title":"Where is your dot?","description":"Last, every time, until the question stops being needed: \"Where is your dot?\""}]', 'The word tin is a THREE-COMPARTMENT tin — naming words, doing words, small joining words — and that sorting is itself the first grammar lesson, done a year before the symbols on Tray 8. The three punctuation tiles are oversized on purpose, so they are objects he places rather than specks he might miss. Keep it to three cards until copying is easy: a four-card sentence a child abandons halfway teaches him that writing is something you do not finish. If there are no gaps in his handwriting, put a lolly stick on the tray as a finger-spacer for a fortnight, then take it away without comment. If he writes a sentence without building it first, that is a good problem — he is ready for Tray 6.', 'The child lays word cards along a sentence line to build a sentence, adds a punctuation tile at the end, reads it aloud, then copies it onto a strip in his own hand. It matters because a child who tries to compose and handwrite at once loses the sentence halfway through — laying it out with cards first finishes all the deciding before the pencil comes out.', 'Berninger et al. (2002) showed that young writers are limited by transcription — handwriting plus spelling — which eats the working memory composing needs; cards move the composing off the pencil entirely. Saddler & Graham (2005) found that working at the level of the sentence improved writing quality more than simply assigning more writing. Move him on when he adds a full stop unprompted to a sentence he invented, leaves gaps in his own handwriting, and builds and copies a three-card sentence in one sitting.', 'Montessori sentence building word cards punctuation tiles early writing'),
    ('ws:6', 'Writing Shelf tray 6 · Story books', '故事书', 'Story books', '4-6', 906, '["Order four wordless pictures into a story of his own","Write one line under each picture, spelling every word by ear","Finish a book: draw the cover and sign his name"]', '["Invented spelling protected — nothing on this tray is checked","Narrative sequence: beginning, middle, end","Writing stamina, because the possibility of being wrong has been removed"]', '["3 wordless picture-sequence sets, 4 frames each, in lettered envelopes: seed → flower, egg → hen, apple → core","6 blank fold-books (one A4 sheet folded to 8 pages)","1 pot of pencils and one of coloured pencils","1 small heart-word card propped at the back — the only reference on this tray"]', 'Only the picture order — it either tells a story when he reads it back or it does not. There is deliberately no spelling control here.', '["Builds and copies a sentence on Tray 5","Writes a word by ear without asking how to spell it"]', 'Four pictures, one blank book, no help. He orders the pictures, writes one line under each in his own book, and draws the cover. Nothing is corrected.', '[{"step":1,"title":"Tip them out","description":"Tip the four pictures out of an envelope, face up, in a muddle."},{"step":2,"title":"Which came first?","description":"Ask: \"Which one happened first?\" Let him decide — a different order is just a different story."},{"step":3,"title":"A row","description":"He lays them in a row, left to right."},{"step":4,"title":"Tell me the story","description":"Say: \"Tell me the story.\" He tells it out loud, all of it.","tip":"Not optional — the story must exist in the air before it exists on paper."},{"step":5,"title":"One page per picture","description":"Give him a fold-book. Show him the four inside pages: one page per picture."},{"step":6,"title":"Write what happens","description":"Point at the first page: \"Write what happens here.\""},{"step":7,"title":"The rule","description":"He asks how to spell something. Say, exactly: \"Say it slowly and write the sounds you hear.\" Same words, every time, forever."},{"step":8,"title":"Go away","description":"Now genuinely go away — sit somewhere else in the room. A teacher standing over a child is a spelling correction that has not been said out loud yet."},{"step":9,"title":"The cover","description":"When he is done he draws the cover and writes his name on it."},{"step":10,"title":"Read it to the class","description":"Read it to the class exactly as he spelled it. Do not silently improve it as you read."}]', 'Three photo sequences, four frames each, no words and no numbers on the fronts and a set letter on the back: seed → flower, egg → hen, apple → core (from spec). The shelf page fixes the format — four cards of about 90 mm per lettered envelope, set letter on the back, never on the cards — and the three sets themselves are named only in the handoffs (sunflower seq-A, egg→hen seq-B, apple→core seq-C), so they are written here plainly and no further detail is invented. Books are folded in advance: a child who has to make the book first never gets to the writing. The heart-word card stays at five words — if it grows to twenty he will copy instead of listen. If he asks you to fix his spelling, say "Not in your book. We do that on the card tray," which keeps the Tray 4 promise credible.', 'The child orders four wordless pictures into a story, then writes one line under each picture in his own small book, spelling every word by ear with no correction at all. It matters because a child who has learned that writing means being right freezes on a blank page — this tray removes the possibility of being wrong, so the writing can actually start.', 'Ouellette & Sénéchal (2017) followed kindergartners encouraged to invent their own spellings and found they read and spelled better a year later than matched children who were not. Inventing a spelling forces the child to break the word into sounds and choose letters, at speed and for his own reasons, which is when it sticks. Move him on when he fills a book to the last page without asking a single spelling, can read his own writing back a week later, and asks for a book with no picture set.', 'wordless picture sequence story writing kindergarten invented spelling fold book'),
    ('ws:7', 'Writing Shelf tray 7 · Author''s chair', '作者椅', 'Author''s chair', '4-6', 907, '["Tell a story of any size, unlimited by what his hand can write","Watch his own spoken words become marks on paper","Cast the class and watch his story acted out from the chair"]', '["Print awareness — the round trip from speech to marks and back to events","Narrative language: one day, suddenly, the end","For a second-language child, the one place his ideas are not shrunk to fit his spelling"]', '["1 folder with 20 story sheets (ruled lines up top for your handwriting, a blank drawing box below)","1 clipboard with the class list and a tick column, so no child is quietly skipped","1 good pen for you, pencils for him","1 chair, kept for this and nothing else"]', 'The audience. If the class can act it, the story made sense. Nothing is marked, nothing is corrected, and the child''s words are not improved on the way down.', '["Has made at least one story book on Tray 6","Can tell a short story out loud"]', 'He talks · you write · the class acts it. He tells the story, you scribe it word for word, he draws underneath, then he casts the class and watches from the chair.', '[{"step":1,"title":"The sheet is yours","description":"Sit down with the sheet in front of you, not him, and the pen in your hand."},{"step":2,"title":"The offer","description":"Say: \"Tell me a story. I will write down exactly what you say.\""},{"step":3,"title":"Keep up","description":"He talks, you write and keep up. If you fall behind say \"wait — let me catch up\", never \"say that again, shorter.\""},{"step":4,"title":"Word for word","description":"Write his words, not better ones. If he says the dog he runned fast, that is what goes on the sheet.","tip":"Tidying it up tells him his own language was not good enough."},{"step":5,"title":"Read it back","description":"When he stops, read the whole thing back to him, out loud."},{"step":6,"title":"One chance to add","description":"Ask once: \"Is that right? Anything else?\" One chance to add. Then it is finished."},{"step":7,"title":"He casts it","description":"Cast it in the corner of the sheet — who plays what. He does the casting."},{"step":8,"title":"Now draw it","description":"Push the sheet across: \"Now draw it.\" He draws in the box while you take the next child."},{"step":9,"title":"The chair","description":"Later, on the carpet: he sits in the chair. You read his story aloud, slowly, exactly as written, and the cast acts it out in the middle."},{"step":10,"title":"Clap for the author","description":"At the end, everyone claps — for the author, not for the acting. Say his name."}]', 'The scribe pad is written WORD FOR WORD, in big print (from spec — the page specifies six wide ruled lines for an adult hand and does not name a size), and is NEVER corrected: his grammar, his word order, his invented words all go down as spoken, and the story is read to the class exactly as written. Four minutes, three actors, no props, ever — props are how story-acting turns into chaos and then gets quietly dropped from the timetable in November. If his story is one line, ask one question and only one: "And then what?" If a child never volunteers, go to him with the folder rather than waiting, and ask in private.', 'The child tells you a story, you write it down word for word while he watches, he draws his own picture underneath, and then the class acts it out while he watches from a chair. It matters because his spoken ideas are far bigger than what his hand can write, and this is the one tray where the size of the story is not limited by his spelling.', 'Nicolopoulou et al. (2015) ran a storytelling-and-story-acting programme in preschool classrooms and measured gains over control classrooms in narrative skill, vocabulary and print knowledge. Cooper (2005) sets out why it works: the child watches his own spoken words become marks on paper, then watches those marks turned back into events by other people. Move him on when he asks to tell a story rather than waiting to be asked, when his story has more than one event in it, and when he writes at least one line of it in his own hand.', 'Vivian Paley storytelling story acting author''s chair preschool dictation'),
    ('ws:8', 'Writing Shelf tray 8 · Grammar symbols', '语法符号', 'Grammar symbols', '4-6', 908, '["Put a black triangle on the naming word of a sentence he wrote himself","Put a red circle on the doing word","Check his own placement against the symbol key"]', '["Grammatical awareness, which predicts later reading comprehension","A word''s JOB given a shape he can hold in his fingers","Oral obedience before written definition — the command game does the teaching"]', '["1 dish of 12 symbols: 4 black triangles (naming, 35 mm), 4 red circles (doing, 30 mm), 4 small dark-blue triangles (describing, 25 mm)","6 sentence strips the child wrote himself on Tray 5 — never a printed sentence from a book","1 symbol key card, kept on the tray","4 miniatures for the oral command game"]', 'The symbol key card, showing which shape means what. He checks his own placement against it, not you.', '["Has written six of his own sentence strips on Tray 5","Has played the oral fetch-and-do command game for weeks, until it is boring"]', 'A game first, a material second. He reads a sentence he built himself, puts a black triangle on the naming word and a red circle on the doing word, then checks the key.', '[{"step":1,"title":"Weeks before the tray: fetch","description":"With no tray at all: put four objects on a mat. \"Bring me the pig.\" He fetches it. Do each object in turn. Explain nothing."},{"step":2,"title":"Then: do","description":"Change the game: \"RUN!\" Shout it, mean it. He runs. \"JUMP!\" \"SIT!\" Still explain nothing."},{"step":3,"title":"Mix them","description":"Mix them: \"Bring me the cat — now HOP with the cat!\" Play it while lining up, while tidying, for weeks, until it is boring."},{"step":4,"title":"Only then, the tray","description":"Put one of his own strips in front of him: the pig is big."},{"step":5,"title":"Which word is the thing?","description":"Ask: \"Which word is the thing?\" He points at pig."},{"step":6,"title":"The black triangle","description":"Hand him the black triangle: \"This shape means a thing.\" He puts it above pig."},{"step":7,"title":"The red circle","description":"On a strip with a doing word — the dog runs — give him the red circle for runs. \"Red, because it moves.\" That is the whole explanation."},{"step":8,"title":"The blue triangle, later","description":"The small dark-blue triangle, for a describing word like big, comes weeks later still: a small triangle because it belongs to the thing."},{"step":9,"title":"He checks the key","description":"He checks his placement against the symbol key himself."},{"step":10,"title":"Two at a time, at most","description":"Never more than two symbols in one session. Three shapes is the whole set for this age."}]', 'Three shapes and no more: black triangle for naming, red circle for doing, small dark-blue triangle for describing — and the control card is the reveal, so he checks himself rather than being marked. Doing the tray presentation before the weeks of oral command game is the single most common way this material fails. Never a printed sentence from a book: his own Tray 5 strip is what makes the shapes mean anything, so on build day the strip slot stays empty until Tray 5 has made six. If he places symbols at random, shelve the tray for a fortnight and go back to fetching and running. If he has learned "the triangle goes on the second word", your sentences all share one shape — vary the word order.', 'The child reads a sentence he wrote himself, places a black triangle over the naming word and a red circle over the doing word, then checks his own work against the symbol key. It matters because he can write the pig is big yet not know which word is the thing and which is what it does — a shape gives that job a form he can hold.', 'Montessori (1918) taught the function of words as a physical command game long before it was ever a written exercise, on the grounds that a five-year-old learns a grammatical category by obeying it rather than by defining it. Cain (2007) found that grammatical awareness in young children predicts later reading comprehension over and above word reading. Move him on when he names a word''s job for a word that was never on a card, finds the naming word in a sentence he has not seen, and moves a wrongly placed symbol before checking the key.', 'Montessori grammar symbols noun triangle verb circle adjective command game')
  ) AS v(
    work_key, name, name_chinese, description, age_range, sequence,
